def comp_stamps(src, panel_top, panel_bottom, fill, edge, bg, W=24):
 # input source area is rows up to panel_top; find components by color in it, excluding bg
 from collections import deque
 out=[[fill]*W for _ in range(panel_bottom-panel_top+1)]
 for r in range(len(out)):
  out[r][0]=out[r][-1]=edge
 # component extraction within source area, cell color==fill
 H=len(src);seen=set()
 for y in range(H):
  for x in range(W):
   if src[y][x]!=fill or (y,x) in seen: continue
   q=deque([(y,x)]);seen.add((y,x)); cells=[]
   while q:
    yy,xx=q.popleft();cells.append((yy,xx))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     ny,nx=yy+dy,xx+dx
     if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and src[ny][nx]==fill:
      seen.add((ny,nx));q.append((ny,nx))
   miny=min(a for a,b in cells);maxy=max(a for a,b in cells)
   top=panel_bottom-(maxy-miny)
   for yy,xx in cells:
    if 0<=top+yy-miny<len(out): out[top+yy-miny][xx]=edge
 return out
